    # leftover ofscraper_community-*.dist-info would report the wrong version
    candidates = sorted(site_packages.glob('ofscraper_community-*.dist-info'))
    candidates += sorted(site_packages.glob('ofscraper-*.dist-info'))
    for dist_info in reversed(candidates):
        for meta_name in ('METADATA', 'PKG-INFO'):
            meta_path = dist_info / meta_name
            if not meta_path.is_file():
                continue
            try:
                text = meta_path.read_text(encoding='utf-8', errors='replace')
            except Exception:
                continue
            match = _re.search(r'^Version:\s*([^\s]+)\s*$', text, _re.MULTILINE)
            if match:
                return match.group(1).strip()
    return None


