def _tool_site_packages(method: str) -> "Path | None":
    """site-packages of the pipx / uv venv that holds ofscraper, if found."""
    try:
        if method == "pipx":
            pkg = _find_pipx_ofscraper_pkg()
        elif method == "uv":
            pkg = _find_uv_ofscraper_pkg()
        else:
            return None
    except Exception:
        return None
    return pkg.parent if pkg else None


def _module_in_site_packages(site_packages: Path, import_name: str) -> bool:
    """True if import_name (e.g. "PyQt6.QtWebEngineWidgets") exists on disk there."""
    *parents, leaf = import_name.split(".")
    base = site_packages.joinpath(*parents)
    if (base / leaf).is_dir():
        return True
    for f in base.glob(leaf + ".*"):
        if f.suffix.lower() in (".py", ".pyd", ".so", ".pyc"):
            return True
    return False


def _check_missing_gui_deps(method: str = "pip") -> list[tuple[str, str, str]]:
    """Return entries from _GUI_DEPS that ofscraper's Python can't import.

    pipx and uv keep ofscraper in its own venv, so their packages are looked
    up in that venv's site-packages, not in the Python running this script
    (which made every GUI package look missing).
    """
    site_packages = _tool_site_packages(method)
    if site_packages is not None:
        return [
            dep for dep in _GUI_DEPS
            if not _module_in_site_packages(site_packages, dep[0])
        ]
    import importlib
    missing = []
    for import_name, pip_name, desc in _GUI_DEPS:
        try:
            importlib.import_module(import_name)
        except ImportError:
            missing.append((import_name, pip_name, desc))
    return missing


def _find_venv_pip(pkg_dir: "Path | None") -> "Path | None":
    """Walk from an ofscraper site-packages dir up to the venv root and find pip."""
    if not pkg_dir:
        return None
    sp_dir = pkg_dir.parent
    parent = sp_dir.parent
    venv_root = (
        parent.parent
        if parent.name.lower() in ("lib", "lib64") or parent.name.lower().startswith("python")
        else parent
    )
    if platform.system() == "Windows":
        for pip_name in ("pip.exe", "pip"):
            candidate = venv_root / "Scripts" / pip_name
            if candidate.exists():
                return candidate
    else:
        candidate = venv_root / "bin" / "pip"
        if candidate.exists():
            return candidate
    return None


def _install_gui_deps(method: str = "pip", *, force: bool = False) -> bool:
    """Install all required GUI dependencies using pip, pipx inject, or uv tool.

    Only installs packages that are not already importable, unless force=True
    (the --force option), which reinstalls every GUI package.  Returns True on
    success (or if nothing was missing).
    """
    if force:
        missing = list(_GUI_DEPS)
        print(f"Reinstalling all GUI dependencies (--force): {', '.join(d for _, _, d in missing)}")
    else:
        missing = _check_missing_gui_deps(method)
        if not missing:
            print("All GUI dependencies already installed.")
            return True

    missing_pip_names = [pip_name for _, pip_name, _ in missing]
    missing_descs = [desc for _, _, desc in missing]
    if not force:
        print(f"Missing GUI dependencies: {', '.join(missing_descs)}")

    run_cwd = os.path.expanduser("~") if method == "pipx" else None

    if method == "uv":
        # uv tool install reinstalls the tool; include ALL deps so none are dropped.
        _py_arg = _uv_python_arg()
        with_args = _uv_with_args(_gui_dep_names())
        if _py_arg:
            print("Installing GUI dependencies via uv (Python 3.12)...")
            print("(uv will download Python 3.12 automatically if not already installed)")
        else:
            print("Installing GUI dependencies via uv...")
        reinstall = ["--force", "--reinstall"] if force else []
        cmd = (["uv", "tool", "install"] + reinstall
               + [f"{PACKAGE_NAME}=={TARGET_OFSCRAPER_VERSION}"] + with_args + _py_arg)

        try:
            subprocess.run(cmd, check=True, capture_output=False)
            print("GUI dependencies installed successfully via uv.")
            return True
        except subprocess.CalledProcessError as e:
            print(f"ERROR: Failed to install GUI dependencies via uv (exit code {e.returncode}).")
            print("Make sure uv is installed and ofscraper was installed via 'uv tool install'.")
            return False
        except FileNotFoundError:
            print("ERROR: Could not find uv. Install it from: https://docs.astral.sh/uv/")
            return False

    elif method == "pipx":
        # Inject each missing package individually.
        print(f"Installing GUI dependencies via pipx inject: {', '.join(missing_pip_names)}")
        all_ok = True
        for pip_name in missing_pip_names:
            print(f"  pipx inject ofscraper {pip_name} ...")
            cmd = ["pipx", "inject"] + (["--force"] if force else []) + [_pipx_venv_name(), pip_name]
            try:
                subprocess.run(cmd, check=True, capture_output=False, cwd=run_cwd)
                print(f"  {pip_name} installed successfully.")
            except subprocess.CalledProcessError as e:
                print(f"  ERROR: Failed to inject {pip_name} (exit code {e.returncode}).")
                print(f"  Trying fallback: installing {pip_name} directly into the pipx venv...")
                venv_pip = _find_venv_pip(_find_pipx_ofscraper_pkg())
                if venv_pip:
                    try:
                        subprocess.run([str(venv_pip), "install"]
                                       + (["--force-reinstall"] if force else []) + [pip_name],
                                       check=True, capture_output=False)
                        print(f"  {pip_name} installed via venv pip fallback.")
                        continue
                    except subprocess.CalledProcessError:
                        pass
                print(f"  Could not install {pip_name}. Make sure pipx is installed.")
                all_ok = False
            except FileNotFoundError:
                _print_pipx_missing()
                return False
        return all_ok

    else:
        # pip — install all missing packages in a single command.
        print(f"Installing GUI dependencies via pip: {', '.join(missing_pip_names)}")
        cmd = ([sys.executable, "-m", "pip", "install"]
               + (["--force-reinstall"] if force else []) + missing_pip_names)
        try:
            subprocess.run(cmd, check=True, capture_output=False)
            print("GUI dependencies installed successfully.")
            return True
        except subprocess.CalledProcessError as e:
            print(f"ERROR: Failed to install GUI dependencies (exit code {e.returncode}).")
            print("You may need to run this script with elevated permissions.")
            return False
        except FileNotFoundError:
            print("ERROR: Could not find pip. Make sure Python and pip are installed.")
            return False


# Linux: the system libraries Qt needs. pip's PyQt6 brings Qt itself but not
# these. The GUI runs on X11 (XWayland on a Wayland desktop), as showing each
# site as a tab needs it, so Qt's xcb platform plugin and its X11 libraries
# must load. Desktop installs often lack some (Ubuntu 26.04 lacks
# libxcb-cursor0 and libgl1), and Qt's error then names xcb-cursor0 whichever
# X11 one is missing; without libGL, PyQt6 doesn't even import.
# (library file, apt package, dnf package, pacman package, zypper package)
_X11_LIBS = [
    ("libGL.so.1", "libgl1", "libglvnd-glx", "libglvnd", "libGL1"),
    ("libEGL.so.1", "libegl1", "libglvnd-egl", "libglvnd", "libEGL1"),
    ("libfontconfig.so.1", "libfontconfig1", "fontconfig", "fontconfig", "libfontconfig1"),
    ("libdbus-1.so.3", "libdbus-1-3", "dbus-libs", "dbus", "libdbus-1-3"),
    ("libxkbcommon.so.0", "libxkbcommon0", "libxkbcommon", "libxkbcommon", "libxkbcommon0"),
    ("libxcb-cursor.so.0", "libxcb-cursor0", "xcb-util-cursor", "xcb-util-cursor", "libxcb-cursor0"),
    ("libxcb-icccm.so.4", "libxcb-icccm4", "xcb-util-wm", "xcb-util-wm", "libxcb-icccm4"),
    ("libxcb-image.so.0", "libxcb-image0", "xcb-util-image", "xcb-util-image", "libxcb-image0"),
    ("libxcb-keysyms.so.1", "libxcb-keysyms1", "xcb-util-keysyms", "xcb-util-keysyms", "libxcb-keysyms1"),
    ("libxcb-randr.so.0", "libxcb-randr0", "libxcb", "libxcb", "libxcb-randr0"),
    ("libxcb-render-util.so.0", "libxcb-render-util0", "xcb-util-renderutil", "xcb-util-renderutil",
     "libxcb-render-util0"),
    ("libxcb-xinerama.so.0", "libxcb-xinerama0", "libxcb", "libxcb", "libxcb-xinerama0"),
    ("libxcb-xkb.so.1", "libxcb-xkb1", "libxcb", "libxcb", "libxcb-xkb1"),
    ("libxcb-shape.so.0", "libxcb-shape0", "libxcb", "libxcb", "libxcb-shape0"),
    ("libxkbcommon-x11.so.0", "libxkbcommon-x11-0", "libxkbcommon-x11", "libxkbcommon-x11", "libxkbcommon-x11-0"),
]

# package manager -> (install command, which package column of _X11_LIBS)
_PACKAGE_MANAGERS = [
    ("apt-get", ["apt-get", "install", "-y"], 1),
    ("dnf", ["dnf", "install", "-y"], 2),
    ("pacman", ["pacman", "-S", "--needed", "--noconfirm"], 3),
    ("zypper", ["zypper", "--non-interactive", "install"], 4),
]


def _desktop_session(env=None) -> str:
    """'wayland', 'x11', or '' when there is no desktop (a server, Docker build)."""
    env = os.environ if env is None else env
    kind = (env.get("XDG_SESSION_TYPE") or "").strip().lower()
    if kind in ("wayland", "x11"):
        return kind
    if env.get("WAYLAND_DISPLAY"):
        return "wayland"
    if env.get("DISPLAY"):
        return "x11"
    return ""


def _library_loads(soname: str) -> bool:
    """Whether the dynamic loader finds the library, as Qt will look for it."""
    import ctypes

    try:
        ctypes.CDLL(soname)
        return True
    except OSError:
        return False


def _missing_x11_libs() -> list:
    return [row for row in _X11_LIBS if not _library_loads(row[0])]


def _x11_install_command(missing: list) -> "list[str] | None":
    """The command that installs the missing libraries, or None when no known
    package manager is found."""
    for exe, cmd, column in _PACKAGE_MANAGERS:
        if shutil.which(exe):
            packages = list(dict.fromkeys(row[column] for row in missing))
            full = cmd + packages
            if hasattr(os, "geteuid") and os.geteuid() != 0 and shutil.which("sudo"):
                full = ["sudo"] + full
            return full
    return None


def _check_x11_libs(*, assume_yes: bool = False, install: bool = True, dry_run: bool = False) -> bool:
    """Linux: find the system libraries the GUI needs and offer to install the
    missing ones. Never stops the patch: returns False when some are still
    missing, and says how to install them."""
    if platform.system() != "Linux":
        return True
    session = _desktop_session()
    if not session:
        print("Desktop session:  none found; skipping the GUI system library check.")
        return True
    if session == "wayland":
        print("Desktop session:  Wayland (the GUI runs on XWayland, which needs the X11 libraries)")
    else:
        print("Desktop session:  X11")
    missing = _missing_x11_libs()
    if not missing:
        print("System libraries for the GUI: all installed.")
        return True
    print(f"Missing system libraries for the GUI: {', '.join(row[0] for row in missing)}")
    cmd = _x11_install_command(missing)
    if cmd is None:
        print("No apt-get, dnf, pacman or zypper found. Install the packages that")
        print("provide those files with your system's package manager.")
        return False
    shown = " ".join(cmd)
    if dry_run:
        print(f"Dry run: would run: {shown}")
        return False
    if not install:
        print(f"Install them with: {shown}")
        return False
    if not assume_yes:
        while True:
            answer = input(f"Install them now with '{shown}'? (yes/no): ").strip().lower()
            if answer in ("yes", "y"):
                break
            if answer in ("no", "n"):
                print(f"Skipped. The GUI won't start until they're installed: {shown}")
                return False
            print("Please enter 'yes' or 'no'.")
    try:
        subprocess.run(cmd, check=True)
    except (subprocess.CalledProcessError, OSError) as e:
        print(f"Could not install them ({e}). Run this yourself: {shown}")
        return False
    still = _missing_x11_libs()
    if still:
        print(f"Still missing after the install: {', '.join(row[0] for row in still)}")
        return False
    print("System libraries installed.")
    return True


def _install_pyqt6(method: str = "pip") -> bool:
    "Kept for backward compatibility — delegates to _install_gui_deps."
    return _install_gui_deps(method)


def _find_older_python():
    "Return a Python 3.11-3.14 executable path if available, else None."
    for candidate in ("python3.12", "python3.13", "python3.11", "python3.14",
                      "python3.12.exe", "python3.13.exe", "python3.11.exe", "python3.14.exe"):
        exe = shutil.which(candidate)
        if exe:
            return exe
    return None


def _pipx_fetch_python_args() -> list[str]:
    "pipx flag to download a standalone Python if it's missing, or [] if this pipx can't."
    try:
        out = subprocess.run(
            ["pipx", "install", "--help"], capture_output=True, text=True, timeout=30
        ).stdout or ""
    except Exception:
        return []
    if _re.search(r"--fetch-python[\s={]", out):
        return ["--fetch-python=missing"]  # newer pipx
    if "--fetch-missing-python" in out:
        return ["--fetch-missing-python"]  # older pipx (1.5+)
    return []


TARGET_OFSCRAPER_VERSION = "3.18.0"


def _run_version_command(cmd: list[str]) -> str | None:
    """Run a version command and return the most likely package x.y.z version found."""
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=10,
        )
    except Exception:
        return None

    candidates: list[str] = []
    combined = result.stdout.splitlines() + result.stderr.splitlines()
    for line in combined:
        line = line.strip()
        if not line:
            continue
        matches = _re.findall(r"(\d+\.\d+\.\d+)", line)
        if matches:
            candidates.extend(matches)

    if not candidates:
        return None

    filtered = [v for v in candidates if v != "0.0.0"]
    if filtered:
        candidates = filtered

    preferred = [v for v in candidates if v.startswith("3.")]
    if preferred:
        candidates = preferred

    return candidates[-1]


def _pipx_ofscraper_exe() -> Path | None:
    """Return the pipx ofscraper executable path if present."""
    if platform.system() == "Windows":
        info = _pipx_ofscraper_info()
        if info:
            metadata = info.get("metadata") or {}
            main_pkg = metadata.get("main_package") or {}
            apps = main_pkg.get("apps") or []
            app_paths = main_pkg.get("app_paths") or []
            for entry in app_paths:
                path = entry.get("__Path__") if isinstance(entry, dict) else None
                if path:
                    candidate = Path(path)
                    if candidate.is_file():
                        return candidate
            for app in apps:
                candidate = shutil.which(app)
                if candidate:
                    return Path(candidate)
            venv_dir = info.get("venv_dir")
            if venv_dir:
                for candidate in [Path(venv_dir) / "Scripts" / "ofscraper.exe", Path(venv_dir) / "Scripts" / "ofscraper"]:
                    if candidate.is_file():
                        return candidate

    pipx_home = _get_pipx_home()
    if not pipx_home:
        return None

    candidates = []
    for name in PACKAGE_NAMES:
        if platform.system() == "Windows":
            candidates.extend([
                pipx_home / "venvs" / name / "Scripts" / "ofscraper.exe",
                pipx_home / "venvs" / name / "Scripts" / "ofscraper",
                pipx_home / "pipx" / "venvs" / name / "Scripts" / "ofscraper.exe",
                pipx_home / "pipx" / "venvs" / name / "Scripts" / "ofscraper",
            ])
        else:
            candidates.append(pipx_home / "venvs" / name / "bin" / "ofscraper")

    for candidate in candidates:
        if candidate.is_file():
            return candidate
    return None


def _pipx_list_json() -> dict | None:
    """Return parsed `pipx list --json` output when available."""
    try:
        result = subprocess.run(["pipx", "list", "--json"], capture_output=True, text=True, timeout=15)
        if result.returncode != 0 or not result.stdout.strip():
            return None
        return json.loads(result.stdout)
    except Exception:
        return None


def _pipx_package_info(package_name: str = "ofscraper") -> dict | None:
    data = _pipx_list_json()
    if not data:
        return None
    venvs = data.get("venvs") or {}
    info = venvs.get(package_name)
    if isinstance(info, dict):
        return info
    return None


def _pipx_ofscraper_info() -> dict | None:
    'pipx metadata for the ofscraper venv, under either package name.'
    for name in PACKAGE_NAMES:
        info = _pipx_package_info(name)
        if info:
            return info
    return None


def _pipx_venv_name() -> str:
    'Name of the pipx venv that holds ofscraper (the new name if none exists yet).'
    for name in PACKAGE_NAMES:
        if _pipx_package_info(name):
            return name
    pipx_home = _get_pipx_home()
    if pipx_home:
        for name in PACKAGE_NAMES:
            if (pipx_home / "venvs" / name).is_dir():
                return name
    return PACKAGE_NAME


def _pipx_list_text() -> str | None:
    """Return plain-text `pipx list` output when available."""
    try:
        result = subprocess.run(["pipx", "list"], capture_output=True, text=True, timeout=15)
        if result.returncode != 0:
            return None
        return result.stdout or ""
    except Exception:
        return None


def _pipx_text_mentions_package(package_name: str | None = None) -> bool:
    text = _pipx_list_text()
    if not text:
        return False
    lowered = text.lower()
    names = [package_name] if package_name else list(PACKAGE_NAMES)
    return any(
        f"package {n.lower()} " in lowered or f" {n.lower()} " in lowered for n in names
    )


def _windows_ofscraper_cli_version() -> str | None:
    if platform.system() != "Windows":
        return None
    exe = shutil.which("ofscraper") or shutil.which("ofscraper.exe")
    if not exe:
        return None
    return _run_version_command([exe, "--version"])


def _uv_ofscraper_exe() -> Path | None:
    """Return the uv tool ofscraper executable path if present."""
    uv_dir = _get_uv_tool_dir()
    if not uv_dir:
        return None

    candidates = []
    for name in PACKAGE_NAMES:
        if platform.system() == "Windows":
            candidates.extend([
                uv_dir / name / "Scripts" / "ofscraper.exe",
                uv_dir / name / "Scripts" / "ofscraper",
            ])
        else:
            candidates.append(uv_dir / name / "bin" / "ofscraper")

    for candidate in candidates:
        if candidate.is_file():
            return candidate
    return None


def _get_installed_ofscraper_version(method: str | None = None) -> str | None:
    """Return the installed ofscraper version string, preferring package metadata over CLI parsing."""
    methods_to_try: list[str] = []
    if method and method != "unknown":
        methods_to_try.append(method)
    for candidate in ("pipx", "uv", "pip"):
        if candidate not in methods_to_try:
            methods_to_try.append(candidate)

    for candidate in methods_to_try:
        if candidate == "pipx":
            info = _pipx_ofscraper_info()
            if info:
                metadata = info.get("metadata") or {}
                main_pkg = metadata.get("main_package") or {}
                version = main_pkg.get("package_version") or info.get("package_version")
                if version:
                    return str(version)
            if _pipx_text_mentions_package():
                exe = _pipx_ofscraper_exe()
                if exe:
                    version = _run_version_command([str(exe), "--version"])
                    if version:
                        return version
                exe_path = shutil.which("ofscraper") or shutil.which("ofscraper.exe")
                if exe_path:
                    version = _run_version_command([exe_path, "--version"])
                    if version:
                        return version
            if platform.system() == "Windows":
                version = _windows_ofscraper_cli_version()
                if version:
                    return version
            pkg = _find_pipx_ofscraper_pkg()
            if pkg:
                version = _read_dist_info_version(pkg)
                if version:
                    return version
            exe = _pipx_ofscraper_exe()
            if exe:
                version = _run_version_command([str(exe), "--version"])
                if version:
                    return version
        elif candidate == "uv":
            pkg = _find_uv_ofscraper_pkg()
            if pkg:
                version = _read_dist_info_version(pkg)
                if version:
                    return version
            exe = _uv_ofscraper_exe()
            if exe:
                version = _run_version_command([str(exe), "--version"])
                if version:
                    return version
        elif candidate == "pip":
            name = _pip_installed_name()
            if name:
                import importlib.metadata
                version = importlib.metadata.version(name)
                if version:
                    return version

    exe = shutil.which("ofscraper")
    if exe:
        version = _run_version_command([exe, "--version"])
        if version:
            return version
    return None


def _gui_dep_names() -> list[str]:
    names = [pip_name for _, pip_name, _ in _GUI_DEPS]
    if _KEEP_POSTGRES_DRIVER:
        # `uv tool install` replaces the tool env: list the driver too, or it's dropped
        names.append(POSTGRES_DRIVER)
    return names


# The optional PostgreSQL driver (installed from the GUI's Merge DBs ->
# PostgreSQL tab). Keep in sync with gui/utils/postgres_setup.DRIVER_REQUIREMENT.
POSTGRES_DRIVER = "psycopg[binary,pool]>=3.3.9,<3.4"
# set by main() when the existing pipx/uv env has the driver: a rebuilt env
# gets it back
_KEEP_POSTGRES_DRIVER = False


def _tool_site_packages(method: str) -> Path | None:
    'site-packages of the pipx or uv tool env that holds ofscraper.'
    if method == "pipx":
        pkg = _find_pipx_ofscraper_pkg()
    elif method == "uv":
        pkg = _find_uv_ofscraper_pkg()
    else:
        return None
    return pkg.parent if pkg else None


def _postgres_driver_present(method: str) -> bool:
    """Whether the pipx/uv env has the PostgreSQL driver. A pip install is
    never rebuilt, so its driver stays without help."""
    site = _tool_site_packages(method)
    return bool(site) and (site / "psycopg").is_dir() and (site / "psycopg_pool").is_dir()


def _tool_python(method: str) -> Path | None:
    'The Python of the pipx/uv env that holds ofscraper.'
    site = _tool_site_packages(method)
    if not site:
        return None
    for venv in site.parents:
        if (venv / "pyvenv.cfg").is_file():
            for exe in (venv / "Scripts" / "python.exe", venv / "bin" / "python"):
                if exe.is_file():
                    return exe
            return None
    return None


def _restore_postgres_driver(method: str, dry_run: bool = False) -> None:
    """Put the PostgreSQL driver back when rebuilding the env dropped it.
    A failure only warns: the GUI's PostgreSQL tab can install it again."""
    if _postgres_driver_present(method):
        print("PostgreSQL driver: kept.")
        return
    if method == "pipx":
        cmd = ["pipx", "inject", _pipx_venv_name(), POSTGRES_DRIVER]
    else:
        python = _tool_python(method)
        if python is None:
            print("WARNING: couldn't find ofscraper's Python to reinstall the PostgreSQL driver.")
            print("         Use Install driver on the GUI's Merge DBs -> PostgreSQL tab.")
            return
        cmd = ["uv", "pip", "install", "--python", str(python), POSTGRES_DRIVER]
    if dry_run:
        print(f"Dry run: would reinstall the PostgreSQL driver: {' '.join(cmd)}")
        return
    print("Reinstalling the PostgreSQL driver (it was installed before)...")
    try:
        subprocess.run(cmd, check=True, capture_output=False, cwd=os.path.expanduser("~"))
        print("PostgreSQL driver reinstalled.")
    except (subprocess.CalledProcessError, FileNotFoundError) as e:
        print(f"WARNING: couldn't reinstall the PostgreSQL driver ({e}).")
        print("         Use Install driver on the GUI's Merge DBs -> PostgreSQL tab.")


def _uv_with_args(pip_names: list[str]) -> list[str]:
    args: list[str] = []
    for pkg in pip_names:
        args += ["--with", pkg]
    return args


def _pipx_install_hint_lines() -> list:
    """How to install pipx on this OS (never an apt command on Windows/macOS)."""
    import importlib.util as _ilu
    system = platform.system()
    py = "python" if system == "Windows" else "python3"
    try:
        module_present = _ilu.find_spec("pipx") is not None
    except Exception:
        module_present = False
    if module_present:
        return [
            "pipx is installed for this Python but is not on your PATH. Run:",
            f"    {py} -m pipx ensurepath",
            "then close this terminal, open a new one and run this script again.",
        ]
    if system == "Windows":
        return [
            "Install it with:",
            "    python -m pip install --user pipx",
            "    python -m pipx ensurepath",
            "then close this terminal, open a new one and run this script again.",
            "(Or choose uv instead, which also handles Python 3.15+.)",
        ]
    if system == "Darwin":
        return [
            "Install it with:",
            "    brew install pipx",
            "    pipx ensurepath",
            "then open a new terminal and run this script again.",
        ]
    return [
        "Install it with your package manager, e.g.:",
        "    sudo apt install pipx      (Debian / Ubuntu)",
        "    sudo dnf install pipx      (Fedora)",
        "    sudo pacman -S python-pipx (Arch)",
        "then run: pipx ensurepath, open a new terminal and run this script again.",
        "More: https://pipx.pypa.io/stable/installation/",
    ]


def _print_pipx_missing() -> None:
    print("ERROR: Could not find pipx.")
    for line in _pipx_install_hint_lines():
        print("       " + line)


def _legacy_install_present(method: str, python_exe: str | None = None) -> bool:
    'True if the "ofscraper-community" package (3.16.2-3.16.13) is installed for this method.'
    if method == "pipx":
        if _pipx_package_info(LEGACY_PACKAGE_NAME):
            return True
        pipx_home = _get_pipx_home()
        return bool(pipx_home and (pipx_home / "venvs" / LEGACY_PACKAGE_NAME).is_dir())
    if method == "uv":
        uv_dir = _get_uv_tool_dir()
        return bool(uv_dir and (uv_dir / LEGACY_PACKAGE_NAME).is_dir())
    try:
        r = subprocess.run(
            [python_exe or sys.executable, "-m", "pip", "show", LEGACY_PACKAGE_NAME],
            capture_output=True, text=True, timeout=60,
        )
        return r.returncode == 0
    except Exception:
        return False


def _remove_legacy_install(method: str, python_exe: str | None = None) -> bool:
    """Uninstall "ofscraper-community" (3.16.2-3.16.13) before installing "ofscraper".

    Both install the same ofscraper/ folder and the same `ofscraper` command,
    so the old one has to go first: uninstalling it afterwards would delete the
    new one's files. Settings, auth and databases in ~/.config/ofscraper are
    not touched. Returns False if the uninstall failed.
    """
    if not _legacy_install_present(method, python_exe):
        return True
    print(f"Removing the '{LEGACY_PACKAGE_NAME}' package; {TARGET_OFSCRAPER_VERSION} is "
          f"published as '{PACKAGE_NAME}' again. Your config, auth and databases are kept.")
    if method == "pipx":
        cmd = ["pipx", "uninstall", LEGACY_PACKAGE_NAME]
        cwd = os.path.expanduser("~")
    elif method == "uv":
        cmd = ["uv", "tool", "uninstall", LEGACY_PACKAGE_NAME]
        cwd = None
    else:
        cmd = [python_exe or sys.executable, "-m", "pip", "uninstall", "-y", LEGACY_PACKAGE_NAME]
        cwd = None
    try:
        subprocess.run(cmd, check=True, capture_output=False, cwd=cwd)
        return True
    except (subprocess.CalledProcessError, FileNotFoundError) as e:
        print(f"ERROR: could not remove the old '{LEGACY_PACKAGE_NAME}' package: {e}")
        print(f"       Remove it yourself with: {' '.join(cmd)}")
        return False


def _pipx_upgrade_in_place(pkg: str) -> bool:
    """Upgrade ofscraper inside its existing pipx venv.

    Keeps the venv's Python (the one it was made with, e.g. 3.12) and the GUI
    packages injected into it. Returns True when the target version is in.
    """
    venv = _pipx_venv_name()
    print(f"Upgrading ofscraper to {TARGET_OFSCRAPER_VERSION} inside the existing pipx venv '{venv}'...")
    cmd = ["pipx", "runpip", venv, "install", "--upgrade", pkg]
    try:
        subprocess.run(cmd, check=True, capture_output=False, cwd=os.path.expanduser("~"))
    except subprocess.CalledProcessError as e:
        print(f"The in-place upgrade failed (exit code {e.returncode}).")
        return False
    except FileNotFoundError:
        _print_pipx_missing()
        return False
    installed = _get_installed_ofscraper_version("pipx")
    if installed != TARGET_OFSCRAPER_VERSION:
        print(f"The in-place upgrade left ofscraper at {installed or 'an undetectable version'}.")
        return False
    print(f"ofscraper {installed} installed successfully.")
    return True


def _install_ofscraper(method: str, *, force: bool = False, keep_gui_deps: bool = False) -> bool:
    """Install or upgrade ofscraper to exactly 3.18.0 via pip, pipx, or uv.
    Returns True on success.

    An "ofscraper-community" package (3.16.2-3.16.13) is removed first; see
    _remove_legacy_install.

    force=True (the --force option) also reinstalls every package instead of
    reusing what is already there, to repair a broken install:
      uv   -> `uv tool install --force --reinstall ... --with <GUI deps>`
      pipx -> `pipx uninstall ofscraper` first, so the venv is created fresh
      pip  -> `--force-reinstall` (already used for every pip install)
    keep_gui_deps=True (--force --skip-deps) reinstalls only ofscraper and its
    own dependencies and keeps the GUI packages that are already installed.
    """
    pkg = f"{PACKAGE_NAME}=={TARGET_OFSCRAPER_VERSION}"
    # 3.18.0 supports Python 3.11+, but lz4 (browser-cookie3) has no 3.15 wheels yet
    is_py313_plus = sys.version_info >= (3, 15)
    py_ver = f"{sys.version_info.major}.{sys.version_info.minor}"
    is_linux = platform.system() == "Linux"
    is_win = platform.system() == "Windows"

    pip_python = None
    if method not in ("pipx", "uv") and is_py313_plus and (is_linux or is_win):
        pip_python = _find_older_python()
    if _legacy_install_present(method, pip_python):
        # the in-place reinstall below can't change the package name
        keep_gui_deps = False
        if not _remove_legacy_install(method, pip_python):
            return False

    if method == "pipx" and not force and _find_pipx_ofscraper_pkg() is not None:
        if _pipx_upgrade_in_place(pkg):
            return True
        # the venv itself can't take it (e.g. its Python is too old): build a
        # new one. `pipx install --force` over an existing venv fails when pipx
        # uses uv ("A virtual environment already exists"), so remove it first.
        print("Rebuilding the pipx venv for ofscraper from scratch...")
        force = True

    if force and method == "pipx" and keep_gui_deps:
        # Reinstall inside the existing venv so injected GUI packages stay.
        print(f"Force-reinstalling ofscraper {TARGET_OFSCRAPER_VERSION} inside the pipx venv (GUI packages kept)...")
        cmd = ["pipx", "runpip", _pipx_venv_name(), "install", "--upgrade", "--force-reinstall", pkg]
        try:
            subprocess.run(cmd, check=True, capture_output=False, cwd=os.path.expanduser("~"))
        except subprocess.CalledProcessError as e:
            print(f"ERROR: Failed to reinstall ofscraper (exit code {e.returncode}).")
            print("If the pipx venv itself is broken, run again with --force but without --skip-deps.")
            return False
        except FileNotFoundError:
            _print_pipx_missing()
            return False
        installed = _get_installed_ofscraper_version(method)
        if installed != TARGET_OFSCRAPER_VERSION:
            print(f"ERROR: Expected ofscraper {TARGET_OFSCRAPER_VERSION} after install, but found {installed or 'nothing detectable'}.")
            return False
        print(f"ofscraper {installed} reinstalled successfully.")
        return True

    if force and method == "pipx" and not keep_gui_deps:
        print("Removing the old pipx install of ofscraper so it is rebuilt from scratch...")
        try:
            subprocess.run(["pipx", "uninstall", _pipx_venv_name()], check=False,
                           capture_output=False, cwd=os.path.expanduser("~"))
        except FileNotFoundError:
            _print_pipx_missing()
            return False

    if method == "uv":
        _py_arg = _uv_python_arg()
        if _py_arg:
            print(f"Installing ofscraper {TARGET_OFSCRAPER_VERSION} via uv with Python 3.12 (for Python {py_ver} compatibility)...")
            print("(uv will download Python 3.12 automatically if not already installed)")
        else:
            print(f"Installing ofscraper {TARGET_OFSCRAPER_VERSION} via uv...")
        cmd = ["uv", "tool", "install", "--force", pkg] + _py_arg
        if force:
            # `uv tool install` replaces the whole tool env, so the GUI packages
            # must be listed or they are dropped.
            reinstall = ["--reinstall-package", PACKAGE_NAME] if keep_gui_deps else ["--reinstall"]
            cmd = ["uv", "tool", "install", "--force"] + reinstall + [pkg] + _uv_with_args(_gui_dep_names()) + _py_arg

    elif is_py313_plus and (is_linux or is_win):
        older_py = _find_older_python()
        if method == "pipx":
            if older_py:
                print(f"Installing ofscraper {TARGET_OFSCRAPER_VERSION} via pipx using {older_py}...")
                print(f"(Using {older_py} because some dependencies lack Python {py_ver} wheels)")
                cmd = ["pipx", "install", "--force", pkg, "--python", older_py]
            elif fetch_args := _pipx_fetch_python_args():
                print(f"Installing ofscraper {TARGET_OFSCRAPER_VERSION} via pipx with Python 3.12...")
                print(f"(Python {py_ver} is too new for some of its pinned dependencies;")
                print(" pipx downloads a standalone Python 3.12 if it isn't installed)")
                cmd = ["pipx", "install", "--force", pkg, "--python", "3.12"] + fetch_args
            else:
                if is_win:
                    print(f"WARNING: Python {py_ver} detected; some dependencies lack Windows wheels for it.")
                    print("         Recommended:")
                    print("           1) Use uv (option 3) — uv can override pinned versions.")
                    print("           2) Install Python 3.11: https://www.python.org/downloads/release/python-3116/")
                    print("           3) Install MSVC Build Tools: https://visualstudio.microsoft.com/visual-cpp-build-tools/")
                else:
                    print(f"WARNING: Python {py_ver} detected but no Python 3.11-3.14 found in PATH.")
                    print("         Recommended fixes:")
                    print("           1) Install Python 3.11:  sudo apt install python3.11")
                    print("              then re-run this script (it will use it automatically).")
                    print("           2) Use uv instead (option 3) — uv can override the pin.")
                print()
                cmd = ["pipx", "install", "--force", pkg]
        else:
            if older_py:
                print(f"Installing ofscraper {TARGET_OFSCRAPER_VERSION} via pip using {older_py}...")
                print(f"(Using {older_py} because some dependencies lack Python {py_ver} wheels)")
                cmd = [older_py, "-m", "pip", "install", "--upgrade", "--force-reinstall", pkg]
            else:
                if is_win:
                    print(f"WARNING: Python {py_ver} detected; some dependencies lack Windows wheels for it.")
                    print("         Recommended:")
                    print("           1) Use uv (option 3) — uv can override pinned versions.")
                    print("           2) Install Python 3.11: https://www.python.org/downloads/release/python-3116/")
                    print("           3) Install MSVC Build Tools: https://visualstudio.microsoft.com/visual-cpp-build-tools/")
                else:
                    print(f"WARNING: Python {py_ver} detected but no Python 3.11-3.14 found in PATH.")
                    print("         Recommended fixes:")
                    print("           1) Install Python 3.11:  sudo apt install python3.11")
                    print("              then re-run this script (it will use it automatically).")
                    print("           2) Use uv instead (option 3) — uv can override the pin.")
                print()
                cmd = [sys.executable, "-m", "pip", "install", "--upgrade", "--force-reinstall", pkg]

    elif method == "pipx":
        print(f"Installing ofscraper {TARGET_OFSCRAPER_VERSION} via pipx...")
        cmd = ["pipx", "install", "--force", pkg]
    else:
        print(f"Installing ofscraper {TARGET_OFSCRAPER_VERSION} via pip...")
        cmd = [sys.executable, "-m", "pip", "install", "--upgrade", "--force-reinstall", pkg]

    try:
        subprocess.run(cmd, check=True, capture_output=False)
    except subprocess.CalledProcessError as e:
        print(f"ERROR: Failed to install ofscraper (exit code {e.returncode}).")
        return False
    except FileNotFoundError:
        if method == "uv":
            print("ERROR: Could not find uv. Install it from: https://docs.astral.sh/uv/")
        elif method == "pipx":
            _print_pipx_missing()
        else:
            print("ERROR: Could not find pip. Make sure Python and pip are installed.")
        return False

    installed = _get_installed_ofscraper_version(method)
    if installed != TARGET_OFSCRAPER_VERSION:
        print(f"ERROR: Expected ofscraper {TARGET_OFSCRAPER_VERSION} after install, but found {installed or 'nothing detectable'}.")
        return False

    print(f"ofscraper {installed} installed successfully.")
    return True


def _prompt_install_method():
    'Interactive menu when ofscraper is not detected. Returns (method, manual_path|None).'
    print()
    print("ofscraper was not detected on this system.")
    print()
    print("Choose an option:")
    print("  1) Install ofscraper with pip")
    print("  2) Install ofscraper with pipx")
    print("  3) Install ofscraper with uv")
    print("  4) Specify install path manually (ofscraper is already installed)")
    print("  5) Exit")
    print()

    method_map = {"1": "pip", "2": "pipx", "3": "uv"}

    while True:
        choice = input("Enter choice (1-5): ").strip()
        if choice in method_map:
            picked = method_map[choice]
            # Catch a missing tool here, before any install warnings, so the
            # user can pick another option instead of the script exiting.
            if picked == "pipx" and shutil.which("pipx") is None:
                print()
                _print_pipx_missing()
                print()
                print("Choose another option, or install pipx and run this script again.")
                continue
            if picked == "uv" and shutil.which("uv") is None:
                print()
                print("ERROR: Could not find uv. Install it from: https://docs.astral.sh/uv/")
                print()
                print("Choose another option, or install uv and run this script again.")
                continue
            return (picked, None)
        if choice == "5":
            return ("exit", None)
        if choice == "4":
            return _prompt_manual_path()
        print("Please enter a number from 1 to 5.")


def _prompt_manual_path():
    'Prompt for a manual ofscraper package path. Returns (method_guess, path_str).'
    print()
    print("Enter the path to your ofscraper package directory")
    print("(the folder containing __main__.py):")

    for attempt in range(3):
        raw = input("> ").strip().strip('"').strip("'")
        if not raw:
            print("No path entered. Please try again.")
            continue

        p = Path(raw).resolve()
        if not p.exists():
            print(f"Path does not exist: {p}")
            if attempt < 2:
                print("Please try again.")
            continue
        if not p.is_dir():
            print(f"Path is not a directory: {p}")
            if attempt < 2:
                print("Please try again.")
            continue
        if not (p / "__main__.py").is_file():
            print(f"Directory does not contain __main__.py: {p}")
            print("Make sure this is the ofscraper package directory.")
            if attempt < 2:
                print("Please try again.")
            continue

        path_lower = str(p).lower()
        if "pipx" in path_lower:
            method = "pipx"
        elif "uv" in path_lower and "tools" in path_lower:
            method = "uv"
        else:
            method = "pip"

        print(f"Path verified: {p}")
        return (method, str(p))

    print("ERROR: Could not validate path after 3 attempts.")
    return ("exit", None)


def _version_tuple(v: str) -> tuple:
    try:
        return tuple(int(x) for x in v.split("."))
    except Exception:
        return (0, 0, 0)


def _check_and_offer_upgrade(method: str) -> bool:
    """Check installed ofscraper version; if missing offer install, if older than target offer upgrade."""
    installed = _get_installed_ofscraper_version(method)

    if installed is None:
        print()
        print(f"ofscraper {TARGET_OFSCRAPER_VERSION} does not appear to be installed.")
        while True:
            answer = input(f"Install ofscraper {TARGET_OFSCRAPER_VERSION} now? (yes/no): ").strip().lower()
            if answer in ("yes", "y"):
                if not _install_ofscraper(method):
                    print("Installation failed.")
                    return False
                return True
            if answer in ("no", "n"):
                while True:
                    ans2 = input("Continue patching without installing? (yes/no): ").strip().lower()
                    if ans2 in ("yes", "y"):
                        return True
                    if ans2 in ("no", "n"):
                        print("Aborted.")
                        return False
                    print("Please enter 'yes' or 'no'.")
            else:
                print("Please enter 'yes' or 'no'.")

    installed_tuple = _version_tuple(installed)
    target_tuple = _version_tuple(TARGET_OFSCRAPER_VERSION)

    if installed_tuple >= target_tuple:
        print(f"Installed ofscraper version: {installed} (OK)")
        return True
    # the patched files import modules an older series doesn't have: patching
    # it anyway leaves ofscraper unable to start
    same_series = installed_tuple[:2] == target_tuple[:2]

    print()
    print(f"Installed ofscraper version: {installed}")
    print(f"This patch is designed for ofscraper {TARGET_OFSCRAPER_VERSION}.")
    if same_series:
        print("Applying it to an older version may not work correctly.")
    else:
        print(f"It can't be applied to {installed}: ofscraper would no longer start.")
    if _legacy_install_present(method):
        print(f"Upgrading removes the '{LEGACY_PACKAGE_NAME}' package first; {TARGET_OFSCRAPER_VERSION} "
              f"is published as '{PACKAGE_NAME}'. Your config, auth and databases are kept.")
    print()

    while True:
        answer = input(f"Upgrade ofscraper to {TARGET_OFSCRAPER_VERSION} now? (yes/no): ").strip().lower()
        if answer in ("yes", "y"):
            if not _install_ofscraper(method):
                print(f"Upgrade failed; nothing was patched. Your ofscraper {installed} is unchanged.")
                return False
            return True
        if answer in ("no", "n"):
            if not same_series:
                print(f"Aborted: this patch needs ofscraper {TARGET_OFSCRAPER_VERSION}.")
                return False
            while True:
                ans2 = input("Continue patching without upgrading? (yes/no): ").strip().lower()
                if ans2 in ("yes", "y"):
                    return True
                if ans2 in ("no", "n"):
                    print("Aborted.")
                    return False
                print("Please enter 'yes' or 'no'.")
        else:
            print("Please enter 'yes' or 'no'.")


def _backup_files(target_pkg: Path, backup_root: Path, rel_paths: list[str]) -> None:
    for rel in rel_paths:
        dst = backup_root / rel
        src = target_pkg / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        if src.exists():
            shutil.copy2(src, dst)


def _apply_zip(target_pkg: Path, zip_bytes: bytes, *, dry_run: bool = False) -> None:
    zf = zipfile.ZipFile(io.BytesIO(zip_bytes), "r")
    for name in zf.namelist():
        if name.startswith("/") or name.startswith("\\") or ".." in Path(name).parts:
            raise RuntimeError(f"Unsafe path in patch zip: {name!r}")
        out_path = target_pkg / name
        if dry_run:
            continue
        out_path.parent.mkdir(parents=True, exist_ok=True)
        with zf.open(name) as src, open(out_path, "wb") as dst:
            shutil.copyfileobj(src, dst)


def restore(backup_dir: Path, target_pkg: Path | None = None) -> None:
    target_pkg = target_pkg or _pick_site_packages_ofscraper_dir()
    backup_dir = Path(backup_dir).resolve()
    if not backup_dir.is_dir():
        raise SystemExit(f"Backup dir does not exist: {backup_dir}")
    for rel in FILES:
        src = backup_dir / rel
        if not src.exists():
            continue
        dst = target_pkg / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)
    print(f"Restored {len(FILES)} file(s) into {target_pkg}")


def apply(*, target: str | None = None, backup_dir: str | None = None, dry_run: bool = False) -> int:
    try:
        target_pkg = Path(target).resolve() if target else _pick_site_packages_ofscraper_dir()
    except Exception as e:
        print(f"ERROR: could not locate installed ofscraper: {e}")
        return 2

    if not target_pkg.exists():
        print(f"ERROR: target package dir does not exist: {target_pkg}")
        return 2

    ts = _dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_root = Path(backup_dir).resolve() if backup_dir else Path(tempfile.gettempdir()) / f"ofscraper_patch_backup_{PATCH_ID}_{ts}"
    if not dry_run:
        backup_root.mkdir(parents=True, exist_ok=True)

    zip_bytes = base64.b64decode(ZIP_B64.encode("ascii"))

    print(f"Patch ID: {PATCH_ID}")
    print(f"Target:   {target_pkg}")
    print(f"Files:    {FILE_COUNT}")
    print(f"Dry-run:  {dry_run}")
    if not dry_run:
        print(f"Backup:   {backup_root}")

    try:
        _backup_files(target_pkg, backup_root, FILES)
        _apply_zip(target_pkg, zip_bytes, dry_run=dry_run)
    except PermissionError as e:
        print(f"ERROR: permission denied writing to {target_pkg}")
        print("Try running this script in an elevated terminal (Administrator).")
        print(f"Details: {e}")
        return 3
    except Exception as e:
        print(f"ERROR: patch failed: {e}")
        if not dry_run:
            print(f"You can restore from backup: {backup_root}")
        return 1

    if dry_run:
        print("Dry-run complete (no files written).")
    else:
        print("Patch applied successfully.")
        print(f'If you need to undo: run with --restore "{backup_root}"')
    return 0


def _detached_gui_kwargs(env=None) -> dict:
    """Popen options that start the GUI on its own: closing this console (e.g.
    the GUI's Update now window) must not close it. The tab-child variables are
    dropped so it opens as its own window, not a frameless embedded tab."""
    env = dict(os.environ if env is None else env)
    env.pop("OFSC_GUI_CHILD", None)
    env.pop("OFSC_GUI_EMBED", None)
    if platform.system() == "Linux" and "QT_QPA_PLATFORM" not in env:
        env["QT_QPA_PLATFORM"] = "xcb"
    kwargs = {
        "cwd": str(Path.home()),
        "env": env,
        "stdin": subprocess.DEVNULL,
        "stdout": subprocess.DEVNULL,
        "stderr": subprocess.DEVNULL,
        "close_fds": True,
    }
    if platform.system() == "Windows":
        # its own process group, and no console window to share
        kwargs["creationflags"] = 0x00000200 | 0x08000000  # NEW_PROCESS_GROUP | NO_WINDOW
    else:
        kwargs["start_new_session"] = True
    return kwargs


def main() -> int:
    ap = argparse.ArgumentParser(
        description="Patch pip/pipx/uv-installed ofscraper 3.18.0 with GUI-enabled files (Windows & Linux).",
    )
    ap.add_argument("--target", help="Explicit path to installed ofscraper package dir (site-packages/ofscraper).")
    ap.add_argument("--backup-dir", help="Where to store backups (defaults to temp).")
    ap.add_argument("--dry-run", action="store_true", help="Print what would happen; don't write files.")
    ap.add_argument("--skip-deps", "--skip-pyqt6", dest="skip_deps", action="store_true",
                    help="Skip automatic GUI dependency installation (PyQt6, PyQt6-WebEngine, browser_cookie3, "
                         "and on Linux the system libraries Qt needs, which are then only listed).")
    ap.add_argument("-y", "--yes", action="store_true", help="Skip the confirmation warning prompt.")
    ap.add_argument("--force", action="store_true",
                    help=f"Reinstall ofscraper {TARGET_OFSCRAPER_VERSION} and all GUI dependencies from scratch, "
                         "then patch. Use it to repair a broken or corrupt install. "
                         "With --skip-deps, only ofscraper is reinstalled.")
    ap.add_argument("--restore", help="Restore from a given backup directory.")
    args = ap.parse_args()

    if args.restore and args.force:
        ap.error("--force can't be used with --restore")

    if args.restore:
        if not _confirm_warning(skip=args.yes):
            print("Aborted.")
            return 0
        restore(Path(args.restore), Path(args.target).resolve() if args.target else None)
        return 0

    if not _confirm_warning(skip=args.yes):
        print("Aborted.")
        return 0

    # Check Python version (ofscraper 3.18.0 requires Python >=3.11; 3.16+ is untested)
    ver = sys.version_info
    print(f"Python version:  {ver.major}.{ver.minor}.{ver.micro}")
    if ver < (3, 11) or ver >= (3, 16):
        print()
        print("WARNING: Python {}.{}.{} detected.".format(ver.major, ver.minor, ver.micro))
        print("         OF-Scraper 3.18.0 and this GUI patch may not work correctly.")
        print("         Recommended Python version: 3.11.x to 3.14.x")
        print()
        while True:
            answer = input("Open browser to download Python 3.11.6? (yes/no): ").strip().lower()
            if answer in ("yes", "y"):
                import webbrowser
                webbrowser.open("https://www.python.org/downloads/release/python-3116/")
                print("Browser opened. Install Python 3.11.6, then re-run this script.")
                return 0
            if answer in ("no", "n"):
                break
            print("Please enter 'yes' or 'no'.")

        while True:
            answer = input("Continue anyway with Python {}.{}.{}? (yes/no): ".format(
                ver.major, ver.minor, ver.micro)).strip().lower()
            if answer in ("yes", "y"):
                break
            if answer in ("no", "n"):
                print("Aborted.")
                return 0
            print("Please enter 'yes' or 'no'.")
        print()

    # Detect platform and install method
    plat = platform.system()
    method = _detect_install_method()
    # a pipx venv that wasn't found where expected: only when nothing else
    # matched, as a pip install also puts `ofscraper` on PATH
    if plat == "Windows" and method == "unknown":
        if _pipx_text_mentions_package() or _windows_ofscraper_cli_version() is not None:
            method = "pipx"
    print(f"Platform:        {plat}")
    print(f"Install method:  {method}")
    print()

    # a pipx/uv env that gets rebuilt below loses packages added to it later
    global _KEEP_POSTGRES_DRIVER
    _KEEP_POSTGRES_DRIVER = method in ("pipx", "uv") and _postgres_driver_present(method)
    if _KEEP_POSTGRES_DRIVER:
        print("PostgreSQL driver found: it will be kept.")
        print()

    just_installed = False
    if method == "unknown":
        choice_method, manual_path = _prompt_install_method()
        if choice_method == "exit":
            print("Aborted.")
            return 0
        if manual_path:
            args.target = manual_path
            method = choice_method
        else:
            if not _install_ofscraper(choice_method):
                return 5
            just_installed = True
            method = choice_method
            method_check = _detect_install_method()
            if method_check != "unknown":
                method = method_check
        print(f"Install method:  {method}")
        print()

    # uv: the forced ofscraper install below already reinstalls the GUI packages.
    gui_deps_done = False
    if args.force and not just_installed:
        what = "ofscraper" if args.skip_deps else "ofscraper and all GUI dependencies"
        if args.dry_run:
            print(f"Dry run: --force would reinstall {what} {TARGET_OFSCRAPER_VERSION} via {method}.")
        else:
            print(f"--force: reinstalling {what} ({TARGET_OFSCRAPER_VERSION}) via {method} from scratch...")
            if not _install_ofscraper(method, force=True, keep_gui_deps=args.skip_deps):
                print("Force reinstall failed.")
                return 5
            gui_deps_done = method == "uv"
        print()
    # Check installed ofscraper version and offer upgrade if < 3.18.0
    elif not _check_and_offer_upgrade(method):
        return 0

    # Re-detect after a potential install so apply() finds the correct location
    if not args.target:
        method_check = _detect_install_method()
        if method_check == "unknown" and plat == "Windows":
            if _pipx_text_mentions_package() or _windows_ofscraper_cli_version() is not None:
                method_check = "pipx"
        if method_check != "unknown":
            if method_check != method:
                method = method_check
                print(f"Install method (re-detected): {method}")
                print()

    if not args.skip_deps and not gui_deps_done:
        force_deps = args.force and not args.dry_run
        if not _install_gui_deps(method, force=force_deps):
            return 4

    if _KEEP_POSTGRES_DRIVER:
        _restore_postgres_driver(method, dry_run=args.dry_run)

    # Linux system libraries; --skip-deps only reports what's missing
    _check_x11_libs(assume_yes=args.yes, install=not args.skip_deps, dry_run=args.dry_run)
    print()

    result = apply(target=args.target, backup_dir=args.backup_dir, dry_run=args.dry_run)
    if result == 0 and not args.dry_run and not args.yes:
        print()
        while True:
            answer = input("Launch OF-Scraper GUI now? (yes/no): ").strip().lower()
            if answer in ("yes", "y"):
                print("Starting OF-Scraper GUI...")
                import os as _os
                _exe = shutil.which("ofscraper")
                if not _exe and method == "pipx":
                    _cand = _pipx_ofscraper_exe()
                    if _cand and _cand.exists():
                        _exe = str(_cand)
                if not _exe and method == "uv":
                    _cand = _uv_ofscraper_exe()
                    if _cand and _cand.exists():
                        _exe = str(_cand)
                if _exe:
                    _cmd = [_exe, "--gui"]
                else:
                    _cmd = [sys.executable, "-m", "ofscraper", "--gui"]
                subprocess.Popen(_cmd, **_detached_gui_kwargs())
                break
            if answer in ("no", "n"):
                break
            print("Please enter 'yes' or 'no'.")
    return result


if __name__ == "__main__":
    raise SystemExit(main())
